CREATE TABLE public.match_missing_players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES public.matches(id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE, player_id uuid NOT NULL REFERENCES public.players(id) ON DELETE CASCADE, reason text NOT NULL DEFAULT 'Injury', custom_reason text, UNIQUE(match_id,player_id)); GRANT SELECT ON public.match_missing_players TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.match_missing_players TO authenticated; GRANT ALL ON public.match_missing_players TO service_role; ALTER TABLE public.match_missing_players ENABLE ROW LEVEL SECURITY; CREATE POLICY "read missing players" ON public.match_missing_players FOR SELECT USING (true); CREATE POLICY "admin write missing players" ON public.match_missing_players FOR ALL TO authenticated USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid())); CREATE TRIGGER archive_missing_players BEFORE DELETE ON public.match_missing_players FOR EACH ROW EXECUTE FUNCTION public.archive_deleted_row();